// src/lib/mcp/tools/list-challenges.ts
var list_challenges_default = defineTool({
  name: "list_challenges",
  title: "Listar desafios de Product Owner",
  description: "Lista os cen\xE1rios de treino de Product Owner (em portugu\xEAs) com id, t\xEDtulo, categoria e n\xEDvel (junior, pleno, senior). Use get_challenge para ver o cen\xE1rio completo.",
  inputSchema: {
    difficulty: z.enum(["junior", "pleno", "senior"]).optional().describe("Filtra pelo n\xEDvel de senioridade.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ difficulty }) => {
    const items = challenges.filter((c) => !difficulty || c.difficulty === difficulty).map((c) => ({
      id: c.id,
      title: c.title,
      category: c.category,
      difficulty: c.difficulty
    }));
    return {
      content: [{ type: "text", text: JSON.stringify(items, null, 2) }],
      structuredContent: { total: items.length, items }
    };
  }
});

// src/lib/mcp/tools/get-challenge.ts
import { defineTool as defineTool2, ToolError } from "npm:@lovable.dev/mcp-js@0.26.2";
import { z as z2 } from "npm:zod@3.25.76";
var get_challenge_default = defineTool2({
  name: "get_challenge",
  title: "Detalhar um desafio de Product Owner",
  description: "Retorna um cen\xE1rio completo de treino de PO: contexto, mensagem do stakeholder, op\xE7\xF5es de decis\xE3o com feedback e impacto, e pontos de aprendizado.",
  inputSchema: {
    id: z2.string().min(1).describe("Id do desafio, obtido em list_challenges."),
    includeAnswers: z2.boolean().optional().describe("Se false, omite qual decis\xE3o \xE9 a ideal e os feedbacks (padr\xE3o: true).")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ id, includeAnswers = true }) => {
    const challenge = challenges.find((c) => c.id === id);
    if (!challenge) throw new ToolError(`Desafio "${id}" n\xE3o encontrado.`);
    const payload = includeAnswers ? challenge : {
      ...challenge,
      decisions: challenge.decisions.map((d) => ({ id: d.id, text: d.text })),
      learningPoints: void 0
    };
    return {
      content: [{ type: "text", text: JSON.stringify(payload, null, 2) }],
      structuredContent: { challenge: payload }
    };
  }
});

