// src/lib/mcp/tools/list-metric-challenges.ts
var list_metric_challenges_default = defineTool3({
  name: "list_metric_challenges",
  title: "Listar desafios de m\xE9tricas",
  description: "Lista os desafios de interpreta\xE7\xE3o de m\xE9tricas de entrega (Lead Time, Cycle Time, Throughput, Velocidade, WIP, Cone da Incerteza, etc.) com id, t\xEDtulo e m\xE9trica.",
  inputSchema: {
    metricName: z3.string().optional().describe("Filtra pelo nome da m\xE9trica (case-insensitive, busca parcial).")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ metricName }) => {
    const needle = metricName?.trim().toLowerCase();
    const items = metricsChallenges.filter((c) => !needle || c.metricName.toLowerCase().includes(needle)).map((c) => ({ id: c.id, title: c.title, metricName: c.metricName }));
    const metrics = [...new Set(metricsChallenges.map((c) => c.metricName))];
    return {
      content: [
        { type: "text", text: JSON.stringify({ metrics, items }, null, 2) }
      ],
      structuredContent: { metrics, total: items.length, items }
    };
  }
});

