// src/lib/mcp/tools/get-client-scenario.ts
var get_client_scenario_default = defineTool6({
  name: "get_client_scenario",
  title: "Cen\xE1rios de cliente para hist\xF3rias de usu\xE1rio",
  description: "Sem id, lista os cen\xE1rios do laborat\xF3rio de hist\xF3rias de usu\xE1rio (cliente, empresa, n\xEDvel, tags). Com id, retorna a transcri\xE7\xE3o completa da conversa com o cliente para praticar escrita de hist\xF3rias.",
  inputSchema: {
    id: z6.string().optional().describe("Id do cen\xE1rio. Omita para listar todos."),
    difficulty: z6.enum(["junior", "pleno", "senior"]).optional().describe("Filtra a listagem pelo n\xEDvel de senioridade.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ id, difficulty }) => {
    if (!id) {
      const items = clientScenarios.filter((s) => !difficulty || s.difficulty === difficulty).map((s) => ({
        id: s.id,
        clientName: s.clientName,
        clientRole: s.clientRole,
        company: s.company,
        difficulty: s.difficulty,
        tags: s.tags
      }));
      return {
        content: [{ type: "text", text: JSON.stringify(items, null, 2) }],
        structuredContent: { total: items.length, items }
      };
    }
    const scenario = clientScenarios.find((s) => s.id === id);
    if (!scenario) throw new ToolError4(`Cen\xE1rio de cliente "${id}" n\xE3o encontrado.`);
    return {
      content: [{ type: "text", text: JSON.stringify(scenario, null, 2) }],
      structuredContent: { scenario }
    };
  }
});

